CREATE TABLE "student_program_enrollments" ("id" serial PRIMARY KEY NOT NULL, "student_id" integer NOT NULL REFERENCES "students"("id") ON DELETE cascade, "program_id" integer NOT NULL REFERENCES "organization_programs"("id") ON DELETE restrict, "dojo_id" integer REFERENCES "dojos"("id") ON DELETE set null, "instructor_id" integer REFERENCES "users"("id") ON DELETE set null, "start_date" timestamp with time zone NOT NULL DEFAULT now(), "end_date" timestamp with time zone, "status" text NOT NULL DEFAULT 'active', "created_at" timestamp with time zone NOT NULL DEFAULT now(), "updated_at" timestamp with time zone NOT NULL DEFAULT now());
ALTER TABLE "student_fee_assignments" ADD COLUMN "program_enrollment_id" integer REFERENCES "student_program_enrollments"("id") ON DELETE set null;
ALTER TABLE "payments" ADD COLUMN "program_enrollment_id" integer REFERENCES "student_program_enrollments"("id") ON DELETE set null;
INSERT INTO "student_program_enrollments" ("student_id", "program_id", "dojo_id", "start_date", "status") SELECT "id", "program_id", "dojo_id", "joinedAt", 'active' FROM "students" WHERE "program_id" IS NOT NULL;
UPDATE "student_fee_assignments" AS assignment SET "program_enrollment_id" = enrollment."id" FROM "student_program_enrollments" AS enrollment WHERE enrollment."student_id" = assignment."student_id" AND enrollment."status" = 'active';
UPDATE "payments" AS payment SET "program_enrollment_id" = assignment."program_enrollment_id" FROM "student_fee_assignments" AS assignment WHERE payment."assignment_id" = assignment."id";
